      if (isPrime(num)) {
        console.log(num);
        return; // Выход из функции при первом найденном простом числе
      }
    }
  }
}

function isPrime(n) {
  if (n < 2) return false;
  for (let I = 2; I <= Math.sqrt(n); i++) {
    if (n % I === 0) {
      return false;
    }
  }
  return true;
}

// Пример вызова функции
const arr = [2, 7, 12, 17, 19];
checkSimpleNumber(arr);
```

В функции `checkSimpleNumber` мы перебираем каждый элемент массива и проверяем его на простоту с помощью функции `isPrime`. Если число больше 1 и является простым числом, мы выводим его на консоль и сразу же возвращаемся из функции, чтобы не проверять остальные элементы массива.

Функция `isPrime` реализует проверку на простоту числа с помощью цикла, проверяющего делители числа от 2 до квадратного корня из числа (согласно теореме о простых числах и делителях). 

Примечание: данная реализация не учитывает специальные случаи (например, числа 0 и 1 не считаются простыми числами, а число 1 обычно не рассматривают в проверке на простоту). Однако в задании этого не требуется.

Для этого примера будем использовать JavaScript и jQuery, а также HTML и CSS для создания модального окна и стиля чата.

Сначала создадим HTML-разметку для модального окна и чата:

```html
<!-- Modal -->
<div class="modal fade" id="chat-modal" tabindex="-1" aria-labelledby="chat-modal-label" aria-hidden="true">
